    "type": "SINGLE",
    "difficulty": 3,
    "stem": "A 44-year-old man presents to the emergency decision unit of Addenbrooke's Hospital Cambridge with clinical findings indicative of Acute Exacerbation of Asthma in NHS Emergency Department. Clinical examination and investigative review confirm back-to-back salbutamol nebulizers with ipratropium, oral prednisolone, and oxygen. Vitals reveal blood pressure of 134/76 mm Hg, heart rate of 68/min, respiratory rate of 18/min, and temperature of 37.2C (98.6F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of acute exacerbation of asthma in nhs emergency department. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
    "options": [
      {
        "text": "Oral broad-spectrum fluoroquinolone monotherapy without microbiological confirmation",
        "correct": false,
        "explanation": "Incorrect: Empiric fluoroquinolones risk severe adverse effects including tendonopathy and select for multidrug-resistant pathogens when unindicated."
      },
      {
        "text": "Back-to-back salbutamol nebulizers with ipratropium, oral prednisolone, and oxygen",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is back-to-back salbutamol nebulizers with ipratropium, oral prednisolone, and oxygen. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Oral bisphosphonate administration during active hypocalcemia",
        "correct": false,
        "explanation": "Incorrect: Potent osteoclast inhibition in hypocalcemic states triggers life-threatening cardiac arrhythmias, tetany, and laryngeal spasm."
      },
      {
        "text": "Intensive intravenous insulin bolus therapy without baseline potassium evaluation",
        "correct": false,
        "explanation": "Incorrect: Rapid insulin infusion shifts extracellular potassium intracellularly, precipitating lethal hypokalemia-induced cardiac arrest."
      },
      {
        "text": "Diagnostic lumbar puncture prior to excluding intracranial mass effect with neuroimaging",
        "correct": false,
        "explanation": "Incorrect: Performing dural puncture in the presence of focal space-occupying lesions risks fatal transtentorial or tonsillar herniation."
      }
    ],
