    "stem": "A 64-year-old man undergoes consultant ward round assessment at Queen Elizabeth Hospital Birmingham with clinical findings indicative of Major Depressive Disorder Moderate in NHS General Practice. Clinical examination and investigative review confirm evidence-based high-intensity psychological intervention CBT or oral SSRI sertraline. Vitals reveal blood pressure of 125/75 mm Hg, heart rate of 69/min, respiratory rate of 17/min, and temperature of 37.9C (98.4F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of major depressive disorder moderate in nhs general practice. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
